import numpy as np

# MECHANISM: Use a piecewise linear function to prioritize bins based on remaining capacity, adjusted for item size

def priority(item, bins):
    threshold = 50
    return np.piecewise(bins - item, [bins - item >= threshold, bins - item < threshold], [lambda x: (x - item) / threshold, lambda x: (threshold - item) / (threshold * 0.5)])

